%dw 2.0
output application/json

// 1. Extraemos las listas de reglas de ambas posiciones del payload
var resultados = payload."0".payload default []
var definiciones = payload."1".payload default []

// 2. Realizamos el cruce (Join) entre resultados (0) y definiciones (1)
var consolidado = resultados map (item0) -> {
    // Buscamos en el catálogo (objeto 1) la regla que coincida con el ID del resultado (objeto 0)
    (definiciones filter ($.idRegla == item0.idRegla) map (item1) -> {
        // --- Datos provenientes de la definición (Posición 1) ---
        idRegla: item1.idRegla,
        nombre: item1.nombre,
        descripcion: item1.descripcion,
        habilitada: item1.habilitada,
        obligatoria: item1.obligatoria,
        aplicaA: item1.aplicaA,
        accion: item1.accion,
        siFalla: item1.siFalla,
        siSeCumple: item1.siSeCumple,
        estadoOrdenComercial: item1.estadoOrdenComercial
    })
}

---
// 3. Aplanamos el resultado para que quede un solo array de objetos
flatten(consolidado)

%dw 2.0
output application/json
---
{
	code: "500",
	messageResponse: "Error Updated Order",
	order: {
		rulesApplied: vars.reglasAcumuladas map (regla) -> {
			idRule: regla.idRegla,
	        isValid: regla.esValido,
	        mandatory: regla.obligatoria,
	        detailedEvaluation: regla.evaluacionDetallada map (detalle) -> {
	            compared: detalle.comparacion,
	            description: detalle.descripcion,
	            mandatory: detalle.obligatoria,
	            result: detalle.resultado
	        },

	        responseRule: {
	            code: regla.respuestaRegla.codigo,
	            message: regla.respuestaRegla.mensaje
	        }
	    }
	}

}

%dw 2.0
output application/json

// ---  VARIABLES ---
var inputData = vars.requestOrder default {}
var orderNum = vars.requestOrder.orderNumber

// ---  FUNCIONES ---
fun findObject(nombreLlave) = 
    (vars.resultadoSapi filter ($.llave == nombreLlave))[0].objeto default null

fun toDate(d) = if (isEmpty(d)) null else { "\$date": d }

fun calcularEstadoComercial(reglas, estadoActual) = do {
    var estadosLimpios = (reglas map (item) -> {
        "esValido": item.esValido default false,
        "estadoOrdenComercial": item.estadoOrdenComercial
    }) orderBy (item) -> item.estadoOrdenComercial.codigo

    var reglasExitosas = estadosLimpios filter (item) -> item.esValido == true
    var todasPasaron = !isEmpty(estadosLimpios) and (sizeOf(reglasExitosas) == sizeOf(estadosLimpios))
    var fechaActual = { "\$date": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"} }
    ---
    if (isEmpty(reglas)) 
        estadoActual // Si no hay reglas, mantenemos el i10
    else if (todasPasaron)
        { 
            "Codigo": p("status-orchestrator.code"), 
            "Descripcion": p("status-orchestrator.description"), 
            "Fecha": fechaActual 
        }
    else if (!isEmpty(reglasExitosas))
        // Si algunas pasaron, tomamos la última exitosa (ej. i20)
        (reglasExitosas[-1].estadoOrdenComercial ++ { "Fecha": fechaActual })
    else 
        estadoActual // Si hay reglas pero NINGUNA se cumplió, mantenemos el i10
}

---
{
    basePath: p("mongo-db-sapi.base-path"),
    host: p("mongo-db-sapi.host"),
    port: p("mongo-db-sapi.port"),
    method: "POST",
    path: "/dynamicQuery",
    body: { 
        "query": {
            "update": "MDM_CD_ORDEN",
            "updates": [
                {
                    "q": { "Numero_Orden": orderNum },
                    "u": {
                        "\$set": {
                            "Fecha_Modificacion": { "\$date": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"} },
                            "Usuario_Modificacion": inputData.updatedBy,

                            // --- ATRIBUTOS CONDICIONALES ---
                            // Solo se mapean si no vienen vacíos en el inputData
                            ("Actualizacion_Extractor": inputData.extractorUpdate) if (!isEmpty(inputData.extractorUpdate)),
                            ("Canal": inputData.channel) if (!isEmpty(inputData.channel)),
                            ("Fase": inputData.phase) if (!isEmpty(inputData.phase)),

                            // Estado Comercial: solo si hay reglas para procesar
                            ("Estado_Orden_Comercial": calcularEstadoComercial(vars.reglasAcumuladas,vars.orderData.result[0].Estado_Orden_Comercial)) if (!isEmpty(vars.reglasAcumuladas)),

                            // Tramite: Mapeo interno condicional
                            ("Tramite": {
                                ("Tipo_Tramite": inputData.through.throughType) if (!isEmpty(inputData.through.throughType)),
                                ("Subtipo_Tramite": inputData.through.throughSubtype) if (!isEmpty(inputData.through.throughSubtype)),
                                ("Fecha_Tramite": toDate(inputData.through.throughDate)) if (!isEmpty(inputData.through.throughDate)),
                                ("Causal_Cancelacion": inputData.through.cancellationReason) if (!isEmpty(inputData.through.cancellationReason))
                                // ... puedes agregar más subcampos aquí siguiendo el mismo patrón
                            }) if (!isEmpty(inputData.through)),

                            ("CUN": inputData.cun) if (!isEmpty(inputData.cun)),

                            // Objetos de MDM y Oferta: solo si la búsqueda retornó algo
                            ("Cliente_Tramite": findObject("MDM_CLIENTE")) if (!isEmpty(findObject("MDM_CLIENTE"))),
                            ("Servicio_Tramite": findObject("CMP_OFERTA_PRODUCTO")) if (!isEmpty(findObject("CMP_OFERTA_PRODUCTO")))
                        }
                    },
                    "upsert": false,
                    "multi": false
                }
            ]
        }
    },
    headers: {
        "client_secret": p('mongo-db-sapi.security.client-secret'),
        "client_id": p('mongo-db-sapi.security.client-id'),
        "name": vars.headers.name,
        "X-CORRELATION-ID": vars.headers."X-CORRELATION-ID",
        "source": vars.headers.source,
        "systemId": vars.headers.systemId
    }
}

