// Filtramos los IDs o códigos de las reglas que fueron exitosas en esta ejecución
var idsReglasExitosas = (vars.reglasAcumuladas filter ($.esValido == true)).idRegla default []
var orderNum = vars.requestOrder.orderNumber

---
{
    basePath: p("mongo-db-sapi.base-path"),
    host: p("mongo-db-sapi.host"),
    port: p("mongo-db-sapi.port"),
    method: "POST",
    path: "/dynamicQuery",
    body: { 
        "query": {
            "update": "MDM_REGLAS_ORDEN", 
            "updates": [
                {
                    // 1. FILTRO: Buscamos el documento por Numero_Orden
                    "q": { "Numero_Orden": vars.requestOrder.orderNumber },

                    // 2. ACTUALIZACIÓN: Usamos el identificador $[regla]
                    "u": {
                        "\$set": {
                            "Reglas_Aplicadas.\$[regla].esValido": true
                        }
                    },
                    "upsert": false,
                    "multi": true,
                    // 3. ARRAY FILTERS: Aquí definimos qué es "regla"
                    "arrayFilters": [
                        { "regla.idRegla": { "\$in": idsReglasExitosas } }
                    ]
                }
            ]
        }
    },
    headers: {
        "client_secret": p('mongo-db-sapi.security.client-secret'),
        "client_id": p('mongo-db-sapi.security.client-id'),
        "name": vars.headers.name,
        "X-CORRELATION-ID": vars.headers."X-CORRELATION-ID",
        "source": vars.headers.source,
        "systemId": vars.headers.systemId
    }
}

