%dw 2.0
output application/json

// Guardamos la respuesta de Mongo en una variable local para facilitar la lectura
var mongoRes = payload.result default {}
var orderNum = vars.requestOrder.orderNumber default ""

---
if (mongoRes.ok == 1) (
    if (mongoRes.n > 0 and mongoRes.nModified > 0)
        {
            code: "200",
            messageResponse: "Update Order Success",
            order: {
                orderNumber: orderNum
            }
        }
    else if (mongoRes.n > 0 and mongoRes.nModified == 0)
        {
            code: "200",
            messageResponse: "Order Not Modified"
        }
    else // Caso donde n == 0
        {
            code: "200",
            messageResponse: "Order Not Found"
        }
)
else // Caso donde ok != 1 (Fallo de sintaxis o error de base de datos)
    {
        code: "500",
        messageResponse: "Error Updated Order",
        order: {
            orderNumber: orderNum
        }
    }

